module TopModule (
    input  logic clk,
    input  logic enable,
    input  logic S,
    input  logic A,
    input  logic B,
    input  logic C,
    output logic Z
);

    logic [7:0] Q;

    always_ff @(posedge clk) begin
        if (enable) begin
            Q <= {Q[6:0], S};
        end
    end

    // ABC: A is MSB, C is LSB
    assign Z = Q[{A, B, C}];

endmodule

module tb_TopModule;
    logic clk;
    logic enable;
    logic S;
    logic A;
    logic B;
    logic C;
    logic Z;

    TopModule uut (
        .clk(clk),
        .enable(enable),
        .S(S),
        .A(A),
        .B(B),
        .C(C),
        .Z(Z)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        enable = 0;
        S = 0;
        {A, B, C} = 3'b000;

        // Apply reset / initial wait
        @(posedge clk);

        // Shift in 8 bits: 1, 0, 1, 1, 0, 0, 1, 0 (MSB first: 1 is first shifted in, ends up at Q[7] or Q[0]?)
        // Wait, let's trace our design: Q <= {Q[6:0], S};
        // If S gets 1, then 0, then 1, etc.
        // Cycle 1: S=1, enable=1 -> Q = 8'h01 (Q[0]=1)
        // Cycle 2: S=0, enable=1 -> Q = 8'h02 (Q[1]=1, Q[0]=0)
        // So bits shifted in sequence appear at Q[0], then shift left.
        // Wait, let's check what the prompt says:
        // "The shift register input should be called S, which feeds the input of Q[0] (MSB is shifted in first)."
        // If MSB is shifted in first, and it feeds Q[0], then the first bit shifted in goes to Q[0], then shifts to Q[1], ..., Q[7].
        // After 8 shifts, the first bit shifted in is at Q[7]!
        // Wait! In our code: `Q <= {Q[6:0], S};`
        // When S=1 first: Q[0] becomes 1. Next cycle, that 1 moves to Q[1], while Q[0] gets new S.
        // So after 8 shifts, the very first bit shifted in has moved all the way to Q[7].
        // The prompt says: "MSB is shifted in first ... when ABC is 000, Z=Q[0], when ABC is 001, Z=Q[1], and so on."
        // Let's verify what values we expect.

        enable = 1;
        // Shift in: 0, 1, 2, 3, 4, 5, 6, 7 (values)
        // Let's shift in sequence: 1, 0, 1, 1, 0, 1, 0, 0
        // Bit 1 (first): goes to Q[0], then Q[1], ... Q[7].
        // Let's test bit by bit and check Z for each ABC combination.

        // Let's shift in 8 known bits: 8'b10101010 (MSB 1, LSB 0).
        // If MSB is shifted in first: S=1, then 0, then 1, then 0, then 1, then 0, then 1, then 0.

        // Bit 1: S=1
        S = 1; @(posedge clk);
        // Bit 2: S=0
        S = 0; @(posedge clk);
        // Bit 3: S=1
        S = 1; @(posedge clk);
        // Bit 4: S=0
        S = 0; @(posedge clk);
        // Bit 5: S=1
        S = 1; @(posedge clk);
        // Bit 6: S=0
        S = 0; @(posedge clk);
        // Bit 7: S=1
        S = 1; @(posedge clk);
        // Bit 8: S=0
        S = 0; @(posedge clk);

        enable = 0; // stop shifting

        // Now check all ABC combinations (0 to 7)
        for (int i = 0; i < 8; i++) {
            {A, B, C} = i[2:0];
            #1;
            $display("ABC = %03b, Z = %b (Expected Q[%0d])", i[2:0], Z, i);
        }

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

