module tb_TopModule;
    logic clk;
    logic enable;
    logic S;
    logic A;
    logic B;
    logic C;
    logic Z;

    TopModule uut (
        .clk(clk),
        .enable(enable),
        .S(S),
        .A(A),
        .B(B),
        .C(C),
        .Z(Z)
    );

    always #5 clk = ~clk;

    initial begin
        integer i;
        logic [7:0] expected_q;

        clk = 0;
        enable = 0;
        S = 0;
        {A, B, C} = 3'b000;

        @(posedge clk);
        #1;

        enable = 1;
        expected_q = 8'b0;

        // Shift in: 1, 0, 1, 0, 1, 0, 1, 0 (MSB first / into S)
        // Let's do a specific sequence: 8'b11001010
        // Shift bits in order: 0, 1, 0, 1, 0, 0, 1, 1

        logic [7:0] test_bits = 8'b11001010; // bit 7 down to 0
        // Wait, if S gets bit 0 first, then bit 1, ... bit 7:
        for (i = 0; i < 8; i = i + 1) begin
            S = test_bits[i];
            @(posedge clk);
            #1;
        end

        enable = 0;

        // Check all Q values via Z
        for (i = 0; i < 8; i = i + 1) begin
            {A, B, C} = i[2:0];
            #1;
            if (Z !== test_bits[i]) begin
                $display("SELFTEST FAIL: At index %0d (ABC=%03b), expected Z=%b, got Z=%b", i, i[2:0], test_bits[i], Z);
                $finish;
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

