        .Z(Z)
    );

    always #5 clk = ~clk;

    initial begin
        integer i;
        logic [7:0] test_bits;

        clk = 0;
        enable = 0;
        S = 0;
        {A, B, C} = 3'b000;
        test_bits = 8'b11001010; // MSB is bit 7 (1), LSB is bit 0 (0)

        @(posedge clk);
        #1;

        enable = 1;

        // Shift in MSB first: test_bits[7] down to test_bits[0]
        for (i = 7; i >= 0; i = i - 1) begin
            S = test_bits[i];
            @(posedge clk);
            #1;
        end

        enable = 0;

        // Check all Q values via Z
        // When ABC = i, Z should equal test_bits[i]
        for (i = 0; i < 8; i = i + 1) begin
            {A, B, C} = i[2:0];
            #1;
            if (Z !== test_bits[i]) begin
                $display("SELFTEST FAIL: At index %0d (ABC=%03b), expected Z=%b, got Z=%b", i, i[2:0], test_bits[i], Z);
                $finish;
            end
        end

